// spec: .qa/e2e/specs/zmanim.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('זמני היום', () => {
  test('ZM-05 «עלות השחר (מג״א, 19.8°)» и «(מג״א, 72 דקות)» в списке вместе с זמנים, что от них считаются #6a86f800 @prod-safe', async ({ page }) => {
    const clean = (s: string) => s.replace(/[‎‏]/g, '').replace(/\s+/g, ' ').trim();
    const time = /\b\d{1,2}:\d{2}\b/;

    // 1. Открыть `/zmanim` (текущий день).
    await page.goto('/zmanim');
    await expect(page.locator('#zmanim-times')).toBeVisible({ timeout: 20_000 });

    // 2. Найти строки «עלות השחר …» и строки «סוף זמן קריאת שמע …» / «סוף זמן תפילה …».
    const rows = [
      { id: 'zman-alot19Point8', label: 'עלות השחר (מג״א, 19.8°)' },
      { id: 'zman-alosBaalHatanya', label: 'עלות השחר (בעל התניא)' },
      { id: 'zman-alotHaShachar', label: 'עלות השחר (16.1°)' },
      { id: 'zman-alot72min', label: 'עלות השחר (מג״א, 72 דקות)' },
      { id: 'zman-sofZmanShmaMGA19Point8', label: 'סוף זמן קריאת שמע (מג״א, 19.8°)' },
      { id: 'zman-sofZmanTfillaMGA19Point8', label: 'סוף זמן תפילה (מג״א, 19.8°)' },
    ];
    for (const r of rows) {
      const row = page.locator(`#${r.id}`);
      await expect(row).toBeVisible();
      expect(clean(await page.locator(`#${r.id}-label`).innerText())).toBe(r.label);
      await expect(page.locator(`#${r.id}-time`)).toHaveText(time);
    }

    // 3. Прочитать пояснение под списком.
    await expect(page.getByText('עלות השחר לשיטת מג״א חושבה באפליקציה לפי הגדרות Hebcal.')).toBeVisible();

    // Нет горизонтальной прокрутки
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
  });
});
